import { ref, onMounted, reactive } from 'vue';
import dayjs from 'dayjs';

export default {
  setup() {
    const chartData = reactive({
      series: {
        series1: { name: 'series#1', show: true, type: 'bar', showValue: { use: true } },
        series2: { name: 'series#2', show: true, type: 'line', combo: true },
      },
      labels: [],
      data: {
        series1: [],
        series2: [],
      },
    });

    const unSelectedOpacity = ref(0.3);
    const chartOptions = reactive({
      width: '100%',
      height: '100%',
      thickness: 0.8,
      unSelectedOpacity,
      title: {
        text: 'Chart Title',
        show: true,
      },
      legend: {
        show: true,
        position: 'right',
      },
      axesX: [
        {
          type: 'time',
          timeFormat: 'HH:mm',
          interval: 'hour',
          categoryMode: true,
          formatter: (value, data) => {
            const curr = dayjs(value).format('YY-MM-DD');
            const prev = data?.prev ? dayjs(data.prev).format('YY-MM-DD') : '';
            if (curr !== prev) {
              return dayjs(value).format('DD HH:mm');
            }

            return dayjs(value).format('HH:mm');
          },
        },
      ],
      axesY: [
        {
          type: 'linear',
          showGrid: true,
          startToZero: true,
          autoScaleRatio: 0.1,
        },
      ],
      selectLabel: {
        use: true,
        limit: 1,
        useDeselectOverflow: true,
        showTip: true,
        fixedPosTop: true,
        useApproximateValue: true,
        tipBackground: '#FF0000',
        useSeriesOpacity: true,
        useLabelOpacity: true,
      },
    });

    const defaultSelectLabel = ref({
      dataIndex: [2],
    });

    const clickedLabel = ref();
    const onClick = ({ selected }) => {
      clickedLabel.value = selected;
    };

    let timeValue = dayjs().format('YYYY-MM-DD HH:mm:ss');

    const addRandomChartData = () => {
      timeValue = dayjs(timeValue).add(1, 'hour');
      chartData.labels.push(dayjs(timeValue));

      Object.values(chartData.data).forEach((seriesData) => {
        const randomValue = Math.floor(Math.random() * (5000 - 5 + 1)) + 5;
        seriesData.push(randomValue);
      });
    };

    onMounted(() => {
      for (let ix = 0; ix < 10; ix++) {
        addRandomChartData();
      }
    });

    return {
      chartData,
      unSelectedOpacity,
      chartOptions,
      defaultSelectLabel,
      clickedLabel,
      onClick,
    };
  },
};
